const items = $input.all();

const MAX_CHARS_PER_CHUNK = 1200;
const MAX_TOTAL_CONTEXT_CHARS = 3500;

function cleanText(text) {
  return (text || '')
    .replace(/Skip to primary content/gi, '')
    .replace(/\|/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

let totalChars = 0;
const contextParts = [];

for (let i = 0; i < items.length; i++) {
  const raw = cleanText(items[i].json.enriched_text || items[i].json.content || '');
  if (!raw) continue;

  const chunkText = raw.slice(0, MAX_CHARS_PER_CHUNK);
  const block = `Source ${i + 1}:\n${chunkText}`;

  if ((totalChars + block.length) > MAX_TOTAL_CONTEXT_CHARS) {
    break;
  }

  contextParts.push(block);
  totalChars += block.length;
}

const context = contextParts.join('\n\n---\n\n');

const sources_text = items
  .map((item, i) => {
    const title = item.json.metadata?.title || `Source ${i + 1}`;
    const url = item.json.metadata?.url || item.json.metadata?.site_url || '';
    const sim = item.json.similarity ? Number(item.json.similarity).toFixed(3) : '';
    return `${i + 1}. ${title}${url ? ' — ' + url : ''}${sim ? ' (similarity: ' + sim + ')' : ''}`;
  })
  .join('\n');

return [
  {
    json: {
      context,
      sources_text,
      results_count: items.length,
      used_chunks: contextParts.length,
      context_length: context.length
    }
  }
];

const q = String($('question_input').first().json.question || '').trim();
const lower = q.toLowerCase();

let semanticTerms = [];
let keywordTerms = [];

if (
  lower.includes('наркоз') ||
  lower.includes('обезбол') ||
  lower.includes('анестез') ||
  lower.includes('седац') ||
  lower.includes('сон')
) {
  semanticTerms.push(
    'седація',
    'лікування уві сні',
    'лікування зубів уві сні',
    'загальний наркоз',
    'лікування під наркозом',
    'лікування зубів під наркозом',
    'штучний сон',
    'анестезіолог',
    'знеболення'
  );

  keywordTerms.push(
    'седація',
    'уві сні',
    'загальний наркоз',
    'під наркозом',
    'штучний сон',
    'знеболення'
  );
}

if (lower.includes('імплант')) {
  semanticTerms.push(
    'імплантація',
    'зубний імплант',
    'вартість імплантації',
    'ціна імплантації'
  );

  keywordTerms.push(
    'імплантація',
    'імплант',
    'ціна',
    'вартість'
  );
}

if (
  lower.includes('чистк') ||
  lower.includes('гигиен') ||
  lower.includes('гігієн')
) {
  semanticTerms.push(
    'професійна чистка зубів',
    'гігієна ротової порожнини',
    'професійне чищення зубів'
  );

  keywordTerms.push(
    'чистка зубів',
    'гігієна',
    'чищення зубів'
  );
}

if (lower.includes('протез')) {
  semanticTerms.push(
    'протезування',
    'коронки',
    'металокераміка',
    'кераміка'
  );

  keywordTerms.push(
    'протезування',
    'коронки',
    'металокераміка',
    'кераміка'
  );
}

const expanded_query = [q, ...semanticTerms].filter(Boolean).join(' ');
const expanded_keywords = [...new Set(keywordTerms)];

return [
  {
    json: {
      question: q,
      expanded_query,
      expanded_keywords
    }
  }
];

const items = $input.all();
const seen = new Set();
const unique = [];

for (const item of items) {
  const id = item.json.id;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  unique.push(item);
}

return unique;

const items = $input.all();

items.sort((a, b) => {
  const simA = Number(a.json.similarity || 0);
  const simB = Number(b.json.similarity || 0);
  return simB - simA;
});

return items.slice(0, 8);

