const items = $input.all();

const combined = items
  .map(item => item.json.output?.[0]?.content?.[0]?.text || '')
  .filter(Boolean)
  .join('\n\n');

return [{
  json: {
    final_text: combined,
    telegram_chat_id: Number($('telegram_input').first().json.telegram_chat_id)
  }
}];

const text = ($json.chatInput || '').toLowerCase();

let answer_language = 'same as user question';

if (/[іїєґ]/i.test(text)) {
  answer_language = 'Ukrainian';
} else if (/[а-яё]/i.test(text)) {
  answer_language = 'Russian';
} else if (/[a-z]/i.test(text)) {
  answer_language = 'English';
}

return [{
  json: {
    ...$json,
    answer_language
  }
}];

